import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor cute_matmul(torch::Tensor A, torch::Tensor B);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>

#include <cute/tensor.hpp>

using namespace cute;

// C = A * B where A is (M,K), B is (K,N), with a small reduction dim K
// (tall-skinny GEMM). CTA tile: 128x128, K-tile: 32, 512 threads.
// Thread -> C mapping: tid -> (m_thr = tid/32, n_thr = tid%32), each thread
// owns a contiguous (8,4) block of C, so every warp store instruction is a
// 128-bit store covering 512B of contiguous C row (coalesced vector writes).
template <bool GUARD>
__global__ void __launch_bounds__(512)
cute_matmul_kernel(const float* __restrict__ Aptr,
                   const float* __restrict__ Bptr,
                   float* __restrict__ Cptr,
                   int M, int N, int K)
{
  constexpr int BM = 128;
  constexpr int BN = 32;
  constexpr int BK = 32;

  const int tid = threadIdx.x;
  // Threadblock-level rasterization (CTA supertile swizzle) for L2 reuse.
  // Consecutive linear CTA ids are mapped onto SWIZZLE_GROUP-wide stripes
  // of M-tiles that sweep across all N-tiles. Concurrently-running CTAs
  // then share the same small set of A-operand tiles (and stream each B
  // tile only briefly) in L2, instead of re-reading the full A operand
  // from DRAM for every column of C tiles. For this write-bound GEMM
  // (huge MxN output, tiny K), operand re-reads are a large fraction of
  // total DRAM traffic, so this directly cuts bytes moved.
  constexpr int SWIZZLE_GROUP = 16;
  const int num_bx = gridDim.x;
  const int num_by = gridDim.y;
  const int linear = blockIdx.y * num_bx + blockIdx.x;
  const int per_group = SWIZZLE_GROUP * num_by;
  const int gid      = linear / per_group;
  const int first_bx = gid * SWIZZLE_GROUP;
  const int gsize    = min(num_bx - first_bx, SWIZZLE_GROUP);
  const int rem      = linear - gid * per_group;
  const int bx = first_bx + rem % gsize;  // M-tile index
  const int by = rem / gsize;             // N-tile index

  // Global tensors. A is (M,K) row-major. B is (K,N) row-major, represented
  // as an (N,K) tensor with stride (1,N) so both operands are (X,K).
  Tensor mA = make_tensor(make_gmem_ptr(Aptr), make_shape(M, K), make_stride(K, Int<1>{}));
  Tensor mB = make_tensor(make_gmem_ptr(Bptr), make_shape(N, K), make_stride(Int<1>{}, N));
  Tensor mC = make_tensor(make_gmem_ptr(Cptr), make_shape(M, N), make_stride(N, Int<1>{}));

  auto cta_tiler = make_shape(Int<BM>{}, Int<BN>{}, Int<BK>{});
  auto cta_coord = make_coord(bx, by, _);

  Tensor gA = local_tile(mA, cta_tiler, cta_coord, Step<_1,  X, _1>{});  // (BM,BK,kt)
  Tensor gB = local_tile(mB, cta_tiler, cta_coord, Step< X, _1, _1>{});  // (BN,BK,kt)
  Tensor gC = local_tile(mC, cta_tiler, cta_coord, Step<_1, _1,  X>{});  // (BM,BN)

  __shared__ __align__(16) float smemA[BM*BK];
  __shared__ __align__(16) float smemB[BN*BK];

  // sA row-major (k contiguous); sB column-major (n contiguous) so that
  // compute-time reads of B are bank-conflict-free across the warp.
  Tensor sA = make_tensor(make_smem_ptr(smemA),
                          make_layout(make_shape(Int<BM>{}, Int<BK>{}),
                                      make_stride(Int<BK>{}, Int<1>{})));
  Tensor sB = make_tensor(make_smem_ptr(smemB),
                          make_layout(make_shape(Int<BN>{}, Int<BK>{}),
                                      make_stride(Int<1>{}, Int<BN>{})));

  // Compute/store thread mapping (512 threads): tid -> (m_thr = tid/32,
  // n_thr = tid%32). The tiny-N case keeps the full N=32 inside the CTA:
  // each thread owns an (8,1) column fragment, lanes in a warp cover 32
  // consecutive n for coalesced stores, and register pressure drops from 32
  // accumulators to 8 to raise occupancy for the write-bound output.
  const int m_thr = tid >> 5;   // 0..15 row-tile
  const int n_thr = tid & 31;   // 0..31 col
  Tensor tCsA = local_tile(sA, make_shape(Int<8>{}, Int<BK>{}), make_coord(m_thr, Int<0>{}));  // (8,BK)
  Tensor tCsB = local_tile(sB, make_shape(Int<1>{}, Int<BK>{}), make_coord(n_thr, Int<0>{}));  // (1,BK)
  Tensor tCgC = local_tile(gC, make_shape(Int<8>{}, Int<1>{}),  make_coord(m_thr, n_thr));     // (8,1)
  Tensor tCrC = make_tensor<float>(make_shape(Int<8>{}, Int<1>{}),
                                   make_stride(Int<1>{}, Int<0>{}));
  clear(tCrC);

  const int kt_max = (K + BK - 1) / BK;

  if constexpr (!GUARD) {
    // Fast path: all tiles in range, vectorized copies.
    // A tile (128,32): 512 threads, 4 threads per row, each loads 8
    // contiguous k (two 16B float4 copies per thread).
    auto copyA = make_tiled_copy(Copy_Atom<UniversalCopy<uint128_t>, float>{},
        make_layout(make_shape(Int<128>{}, Int<4>{}), make_stride(Int<4>{}, Int<1>{})),
        make_layout(make_shape(Int<1>{}, Int<8>{})));
    // B tile (32,32): consecutive threads read consecutive n (coalesced),
    // 16 k-groups of 2 elements per thread.
    auto copyB = make_tiled_copy(Copy_Atom<UniversalCopy<float>, float>{},
        make_layout(make_shape(Int<32>{}, Int<16>{}), make_stride(Int<1>{}, Int<32>{})),
        make_layout(make_shape(Int<1>{}, Int<2>{})));

    auto thrA = copyA.get_slice(tid);
    auto thrB = copyB.get_slice(tid);

    Tensor tAgA = thrA.partition_S(gA);  // (CPY,CPY_M,CPY_K,kt)
    Tensor tAsA = thrA.partition_D(sA);
    Tensor tBgB = thrB.partition_S(gB);
    Tensor tBsB = thrB.partition_D(sB);

    for (int kt = 0; kt < kt_max; ++kt) {
      copy(copyA, tAgA(_, _, _, kt), tAsA);
      copy(copyB, tBgB(_, _, _, kt), tBsB);
      __syncthreads();
      gemm(tCsA, tCsB, tCrC);   // (16,K)x(4,K) -> (16,4) rank-k update
      __syncthreads();
    }
    // Coalesced 128B warp stores: lanes hold consecutive n for one row.
    #pragma unroll
    for (int i = 0; i < 8; ++i) {
      tCgC(i, 0) = tCrC(i, 0);
    }
  } else {
    // Guarded general path (any M, N, K).
    const int m0 = bx * BM;
    const int n0 = by * BN;

    const int mA_l = tid >> 2;
    const int kA_h = tid & 3;
    const int nB_l = tid & 31;
    const int kB_h = tid >> 5;

    for (int kt = 0; kt < kt_max; ++kt) {
      const int k0 = kt * BK;
      {
        const int gm = m0 + mA_l;
        #pragma unroll
        for (int v = 0; v < 8; ++v) {
          const int k = kA_h * 8 + v;
          float val = 0.0f;
          if (gm < M && (k0 + k) < K) val = gA(mA_l, k, kt);
          sA(mA_l, k) = val;
        }
        const int gn = n0 + nB_l;
        #pragma unroll
        for (int v = 0; v < 2; ++v) {
          const int k = kB_h * 2 + v;
          float val = 0.0f;
          if (gn < N && (k0 + k) < K) val = gB(nB_l, k, kt);
          sB(nB_l, k) = val;
        }
      }
      __syncthreads();
      gemm(tCsA, tCsB, tCrC);
      __syncthreads();
    }

    #pragma unroll
    for (int i = 0; i < 8; ++i) {
      const int gm = m0 + m_thr * 8 + i;
      if (gm >= M) continue;
      const int gn = n0 + n_thr;
      if (gn < N) tCgC(i, 0) = tCrC(i, 0);
    }
  }
}

torch::Tensor cute_matmul(torch::Tensor A, torch::Tensor B) {
  TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
  TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D");
  TORCH_CHECK(A.scalar_type() == at::kFloat && B.scalar_type() == at::kFloat,
              "Expect float32 tensors");

  const int64_t M = A.size(0);
  const int64_t K = A.size(1);
  const int64_t N = B.size(1);
  TORCH_CHECK(B.size(0) == K, "B.size(0) must equal A.size(1)");

  auto A_c = A.contiguous();
  auto B_c = B.contiguous();
  auto C   = torch::empty({M, N}, A.options());

  dim3 block(512);
  dim3 grid((unsigned)((M + 127) / 128), (unsigned)((N + 31) / 32));
  TORCH_CHECK(grid.y <= 65535, "N too large for grid.y");

  const bool even = (M % 128 == 0) && (N % 32 == 0) && (K % 32 == 0);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  if (even) {
    cute_matmul_kernel<false><<<grid, block, 0, stream>>>(
        A_c.data_ptr<float>(), B_c.data_ptr<float>(), C.data_ptr<float>(),
        (int)M, (int)N, (int)K);
  } else {
    cute_matmul_kernel<true><<<grid, block, 0, stream>>>(
        A_c.data_ptr<float>(), B_c.data_ptr<float>(), C.data_ptr<float>(),
        (int)M, (int)N, (int)K);
  }

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "CUTE matmul launch failed: ",
              cudaGetErrorString(err));

  return C;
}
"""

cute_matmul_ext = load_inline(
    name="cute_tall_skinny_matmul_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_matmul"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    C = A * B (tall-and-skinny GEMM, small reduction dim K) implemented with a
    single custom CUTE CUDA kernel: 128x128 CTA tiles, K-tile of 32 staged in
    shared memory, register-blocked (16x4) fragments per thread, and fully
    coalesced stores of the large output matrix. A CTA supertile swizzle
    (threadblock rasterization) groups concurrently-running CTAs so they
    share A/B operand tiles in L2, cutting DRAM re-reads of the operands.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = cute_matmul_ext

    def forward(self, A, B):
        return self._ext.cute_matmul(A, B)

