  const int first_bx = gid * SWIZZLE_GROUP;
  const int gsize    = min(num_bx - first_bx, SWIZZLE_GROUP);
  const int rem      = linear - gid * per_group;
  const int bx = first_bx + rem % gsize;  // M-tile index
  const int by = rem / gsize;             // N-tile index

